create or replace TABLE KFL_PRODUCTION.DBP_DATA.HANDLING_UNIT (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant 1 steht im DWH für Deutschland (der Wert 22 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle. der Marktnummer die Nebenbetriebskennziffer.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	HANDLING_UNIT_ID NUMBER(18,0) NOT NULL COMMENT 'Interne Handling Unit Nummer.',
	PACKMITTEL_TYP VARCHAR(1) COLLATE 'en-ci' COMMENT 'Packmitteltyp.',
	HU_GEW_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Gewichtseinheit.',
	HU_VOL_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Volumeneinheit.',
	LAGERNUMMER_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'ID der Lagernummer - höchste Ebene der Lagerhierarchie.',
	PACKMITTELART_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Packmittelart.',
	MAT_GRU_PACKMITTEL VARCHAR(4) COLLATE 'en-ci' COMMENT 'Materialgruppe Packmittel.',
	VERSANDSTELLE_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Ort, an dem Lieferungen bearbeitet werden. Es kann sich dabei um einen physischen Ort (z.B. ein Lager oder eine Gruppe von Laderampen) oder um eine logische Gruppierung (z.B. eine Gruppe von Personen, die für die Versandaktivitäten zuständig ist) handeln.',
	GEWICHT_LADUNG NUMBER(9,3) COMMENT 'Ladungsgewicht der Handling Unit.',
	GEWICHT_EIGEN NUMBER(9,3) COMMENT 'Eigengewicht der Handling Unit.',
	VOL_LADUNG NUMBER(18,3) COMMENT 'Ladungsvolumen der Handling Unit.',
	VOL_EIGEN NUMBER(18,3) COMMENT 'Eigenvolumen der Handling Unit.',
	VERSANDEINHEIT_ID NUMBER(18,0) NOT NULL COMMENT 'Träger-Nummer-Versand-Einheit (bei Sammelpalette). Enthält 18-stelligen Nummer, wenn Teil einer Palette, -1 wenn Palette, 1 wenn Sammelpalette.',
	HANDLING_UNIT_ID_EXT VARCHAR(20) COLLATE 'en-ci' COMMENT 'Externe Handling Unit Identifikation aus exidv. Nummer der Versandeinheit (NVE).',
	LIEF_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID des Lieferscheins und dient der eindeutigen Identifikation der Lieferscheinbelege. Referenziert auf vekp.vpobjkey.',
	ANZAHL_STELLPLATZ NUMBER(9,2) NOT NULL COMMENT 'Anzahl der für die Handling Unit benötigten Stellplätze.',
	MENGE_GEFAHRGUT NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Gefahrgutmenge aus dem Feld zlvgefmenge_nve. Einheit ist immer in Litern.',
	BRTVOL_LADUNG NUMBER(18,3) NOT NULL COMMENT 'Das Bruttovolumen der Ladung. kann wegen mangelnder Datenqualität nicht aus Netto + Tara ermittelt werden. Quelle ist btvol.',
	BRTGEW_LADUNG NUMBER(18,3) NOT NULL COMMENT 'Das Bruttogewicht der Ladung. kann wegen mangelnder Datenqualität nicht aus Netto + Tara ermittelt werden. Quelle ist brgew.',
	MENGE_HANDLING_KOLLI_ORIG NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Kollimenge aus dem Feld zlv_kolli.',
	HU_STATUS_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Bewegungsstatus der Handling Unit.',
	HU_STELLPLATZ_FAKTOR NUMBER(9,2) COMMENT 'ID Bewegungsstatus der Handling Unit.',
	BRTVOL_LADUNG_GEDECKELT NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Das Bruttovolumen der Ladung. kann wegen mangelnder Datenqualität nicht aus Netto + Tara ermittelt werden (Deckelung des Volumens der einzelnen HU auf max. 2304 cdm). Quelle ist btvol.',
	KJ_LIEF_BELEG NUMBER(38,0) COMMENT 'Kalenderjahr Format JJJJ.',
	GEWICHT_GESAMT NUMBER(9,3) COMMENT 'Gesamtgewicht der Handling Unit.',
	HANDLE VARCHAR(22) COMMENT 'Weltweit eindeutiger Schlüssel für VEKP-VENUM.',
	HANDLING_UNIT_ID_PARENT NUMBER(18,0) COMMENT 'Übergeordnete Handling Unit.',
	HANDLING_UNIT_IDART_EXT VARCHAR(1) COMMENT 'Art der externen Handling Unit Identifiaktion.',
	VERPACK_BELEG_TYP_ID VARCHAR(2) COMMENT 'Verpackungsobjekt.',
	VOL_GESAMT NUMBER(18,3) COMMENT 'Gesamtvolumen der Handling Unit.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	DAT_ERSTELLUNG DATE COMMENT 'Erstellungsdatum (ERDAT) aus Quelltabelle VEKP.',
	DAT_AENDERUNG DATE COMMENT 'Letztes Änderungsdatum (AEDAT) aus Quelltabelle VEKP.',
	constraint PK_HANDLING_UNIT primary key (MANDANT_ID, VERSANDSTELLE_ID, SYSTEM_ID, NB_ID, WUP_ID, HANDLING_UNIT_ID)
)COMMENT='TP408_LVS Kopftabelle der Handling-Unit. Quelle ist in SAP die Tabelle VEKP.'
;